"""Seating rows built from a list of students."""

from typing import List

from rosterkit.models import Student

def _sort_key(student: Student) -> tuple:
    first = student.first_name.lower()
    return (student.last_name.lower(), first)

def _check_inputs(students: list, seats: int) -> None:
    if seats <= 0:
        raise ValueError(f"seats must be positive: {seats}")
    if not students:
        raise ValueError("no students to seat")

def _format_row(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

def _split(roster: List[Student], size: int) -> list:
    starts = range(0, len(roster), size)
    return [roster[start:start + size] for start in starts]

def _number_rows(groups: list) -> List[str]:
    pairs = enumerate(groups, 1)
    return [_format_row(*pair) for pair in pairs]

# ---
def seating_rows(students, seats_per_row) -> List[str]:
    """One line per row, students sorted by last name."""
    roster = sorted(students, key=_sort_key)
    _check_inputs(roster, seats_per_row)
    return _number_rows(_split(roster, seats_per_row))

